begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public, pg_temp;
select plan(24);
select has_table('platform_global_authorities');
select has_table('platform_global_delegations');
select has_table('global_competency_concepts');
select has_table('global_competency_concept_versions');
select has_table('global_competency_aliases');
select has_table('tenant_competency_mappings');
select has_table('tenant_competency_mapping_audit');
select col_is_pk('platform_global_capabilities','capability');
select ok(exists(select 1 from pg_constraint where conname='development_templates_id_company_id_key'),'template candidate key exists');
select ok(exists(select 1 from pg_constraint where conname='development_template_goals_competency_company_fkey' and convalidated),'company competency FK validated');
select ok(exists(select 1 from pg_constraint where conname='development_template_goals_template_company_fkey' and convalidated),'template company FK validated');
set local role authenticated;
select throws_ok($$select public.bootstrap_platform_global_authority(gen_random_uuid(),'bootstrap_actor')$$,'42501',null,'authenticated cannot execute trusted bootstrap');
reset role;
insert into auth.users(id,email) values('67000000-0000-4000-8000-000000000001','owner@example.com'),('67000000-0000-4000-8000-000000000002','manager@example.com');
insert into companies(id,name,slug) values('67000000-0000-4000-8000-000000000101','Alpha','global-alpha'),('67000000-0000-4000-8000-000000000102','Beta','global-beta');
insert into company_members(company_id,user_id,role) values('67000000-0000-4000-8000-000000000101','67000000-0000-4000-8000-000000000001','owner'),('67000000-0000-4000-8000-000000000101','67000000-0000-4000-8000-000000000002','manager');
insert into competencies(id,company_id,name,category) values('67000000-0000-4000-8000-000000000201','67000000-0000-4000-8000-000000000101','Leadership','leadership'),('67000000-0000-4000-8000-000000000202','67000000-0000-4000-8000-000000000102','Other','technical');
insert into global_competency_concepts(id,code,created_by) values('67000000-0000-4000-8000-000000000301','mapping_concept','67000000-0000-4000-8000-000000000001');
insert into global_competency_concept_versions(id,concept_id,version_number,name,definition,category,created_by) values('67000000-0000-4000-8000-000000000302','67000000-0000-4000-8000-000000000301',1,'Mapping Concept','Definition','technical','67000000-0000-4000-8000-000000000001');
insert into development_templates(id,company_id,name,scope,created_by) values('67000000-0000-4000-8000-000000000401','67000000-0000-4000-8000-000000000101','Company Template','company','67000000-0000-4000-8000-000000000001');
select lives_ok($$insert into development_template_goals(template_id,company_id,competency_id,description,suggested_target_level) values('67000000-0000-4000-8000-000000000401','67000000-0000-4000-8000-000000000101','67000000-0000-4000-8000-000000000201','Goal',3)$$,'company-owned template flow remains valid');
set local role service_role;
select lives_ok($$select public.bootstrap_platform_global_authority('67000000-0000-4000-8000-000000000001','bootstrap_actor')$$,'bootstrap is trusted and audited');
select lives_ok($$select public.manage_global_competency_catalog('67000000-0000-4000-8000-000000000001','create_concept','{"code":"leadership"}','create_concept')$$,'curator creates draft concept');
reset role;
select is((select count(*) from platform_global_authority_audit where operation='bootstrap'),7::bigint,'bootstrap audits each capability');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"67000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$insert into global_competency_concepts(code,created_by) values('direct_write','67000000-0000-4000-8000-000000000001')$$,'42501',null,'client cannot write global catalog');
select throws_ok($$insert into tenant_competency_mappings(company_id,concept_version_id,competency_id,proposed_by) values('67000000-0000-4000-8000-000000000101','67000000-0000-4000-8000-000000000302','67000000-0000-4000-8000-000000000201','67000000-0000-4000-8000-000000000001')$$,'42501',null,'client cannot bypass audited mapping command');
select throws_ok($$select public.save_tenant_competency_mapping('67000000-0000-4000-8000-000000000101','67000000-0000-4000-8000-000000000302','67000000-0000-4000-8000-000000000202','propose',null,'cross_tenant')$$,'23503',null,'cross tenant mapping rejected');
select set_config('request.jwt.claims','{"sub":"67000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.save_tenant_competency_mapping('67000000-0000-4000-8000-000000000101','67000000-0000-4000-8000-000000000302','67000000-0000-4000-8000-000000000201','propose',null,'manager_attempt')$$,'TENANT_MAPPING_FORBIDDEN');
reset role;
select ok((select relrowsecurity from pg_class where oid='tenant_competency_mappings'::regclass),'mapping RLS enabled');
select ok((select relrowsecurity from pg_class where oid='global_competency_concepts'::regclass),'global concept RLS enabled');
select throws_ok($$update platform_global_authority_audit set reason='changed'$$,'55000','GLOBAL_AUDIT_APPEND_ONLY','authority audit append-only');
select ok(not exists(select 1 from pg_constraint where conname='development_template_goals_competency_id_fkey'),'simple competency FK removed');
select * from finish();
rollback;
